// ============================================
// VALIDATION INPUT - MCP Tenant Resolve
// RFC-049 Entity Storage Architecture
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- REQUIRED fields ---
const action = body.action || ctx.action;
const userId = body.user_id || ctx.user_id;

// --- OPTIONAL fields ---
const guildId = body.guild_id || ctx.guild_id || null;

if (!action) {
  errors.push('action requis');
} else if (action !== 'resolve') {
  errors.push('action doit etre "resolve"');
}

if (!userId) {
  errors.push('user_id requis');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId
  };
}

return {
  valid: true,
  action: action,
  user_id: userId,
  guild_id: guildId,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'n8n',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', ')
  }
};

// ============================================
// BUILD SUCCESS RESPONSE
// RFC-049 Entity Storage Architecture
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

const latencyMs = Date.now() - startTime;

return {
  success: true,
  data: {
    tenant_id: input.tenant_id,
    user_id: prevData.user_id,
    subscription_status: input.subscription_status || 'active'
  },
  _trace: {
    service_response: input,
    provider: 'api-backend',
    mode: 'resolve',
    latency_ms: latencyMs,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id
  }
};

// ============================================
// BUILD NOT FOUND ERROR
// RFC-049 Entity Storage Architecture
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

const latencyMs = Date.now() - startTime;

return {
  success: false,
  error: {
    code: 'USER_NOT_FOUND',
    message: `No tenant found for user_id ${prevData.user_id}`
  },
  _trace: {
    service_response: input,
    provider: 'api-backend',
    mode: 'error',
    latency_ms: latencyMs,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id
  }
};
